"""Unit checks for tools/inline_parts.py (run: python3 -m pytest .github/scripts).

Pure stdlib: every module here is a fixture written into tmp_path, so nothing
needs a CAD kernel. The real repository is checked once at the end — that is the
same `--check` the manifests lane runs as its own step.
"""

import importlib.util
import pathlib
import subprocess

import pytest

REPO = pathlib.Path(__file__).resolve().parents[2]
spec = importlib.util.spec_from_file_location("inline_parts", REPO / "tools" / "inline_parts.py")
ip = importlib.util.module_from_spec(spec)
spec.loader.exec_module(ip)

SPDX = ip.SPDX_LINE


def module(requires="", body="def a(p):\n    return p\n", doc='"""Doc."""\n'):
    return f"{SPDX}\n# requires: {requires}\n{doc}\n\n{body}"


def family(directive="# inline-parts: alpha", extra=""):
    return f'"""A family."""\n\nx = 1\n\n{directive}\n\n\n{extra}result = a(x)\n'


@pytest.fixture
def repo(tmp_path):
    hw = tmp_path / ip.HARDWARE
    hw.mkdir(parents=True)
    (hw / "base.py").write_text(module(body="def helper(s):\n    return s\n"))
    (hw / "alpha.py").write_text(module("base", "def a(p):\n    return helper(p)\n"))
    (tmp_path / "fam").mkdir()
    (tmp_path / "fam" / "family.py").write_text(family())
    return tmp_path


def write(repo, slug="fam"):
    assert ip.main(["--root", str(repo), "--write", slug]) == 0


def test_blob_sha_is_git_hash_object(tmp_path):
    assert ip.blob_sha(b"") == "e69de29bb2d1d6434b8b29ae775ad8c2e48c5391"
    assert ip.blob_sha(b"hello\n") == "ce013625030ba8dba906f756967f9e9ca394464a"
    path = tmp_path / "f.py"
    path.write_bytes("# ünïcode\n".encode())
    git = subprocess.run(["git", "hash-object", str(path)], capture_output=True, text=True)
    if git.returncode == 0:
        assert ip.blob_sha(path.read_bytes()) == git.stdout.strip()


def test_generate_inlines_requirements_first_between_markers(repo):
    text = ip.generate(repo, "fam")
    base = (repo / ip.HARDWARE / "base.py").read_bytes()
    alpha = (repo / ip.HARDWARE / "alpha.py").read_bytes()
    begin_base = ip.begin_marker("base", ip.blob_sha(base))
    begin_alpha = ip.begin_marker("alpha", ip.blob_sha(alpha))
    assert text.startswith("# GENERATED by tools/inline_parts.py")
    assert text.index("# inline-parts: alpha") < text.index(begin_base) < text.index(begin_alpha)
    assert begin_base + "\n" + base.decode() + ip.end_marker("base", ip.blob_sha(base)) + "\n" in text
    assert text.rstrip().endswith("result = a(x)")
    assert [(n, s) for n, s, _ in ip.inlined_blocks(text)] == [
        ("base", ip.blob_sha(base)), ("alpha", ip.blob_sha(alpha))]
    # The family's own text survives verbatim around the blocks.
    head, tail = family().split("# inline-parts: alpha\n")
    assert head in text and tail in text


def test_generated_main_executes_as_one_script(repo):
    namespace = {}
    exec(ip.generate(repo, "fam"), namespace)  # noqa: S102
    assert namespace["result"] == 1


def test_a_module_required_twice_is_inlined_once(repo):
    (repo / ip.HARDWARE / "beta.py").write_text(module("base", "def b(p):\n    return helper(p)\n"))
    (repo / "fam" / "family.py").write_text(family("# inline-parts: alpha beta"))
    names = [n for n, _, _ in ip.inlined_blocks(ip.generate(repo, "fam"))]
    assert names == ["base", "alpha", "beta"]


def test_check_passes_after_write_and_is_idempotent(repo):
    write(repo)
    first = (repo / "fam" / "main.py").read_text()
    assert ip.check(repo) == []
    write(repo)
    assert (repo / "fam" / "main.py").read_text() == first


def test_check_fails_when_a_module_changes_without_regeneration(repo):
    write(repo)
    (repo / ip.HARDWARE / "base.py").write_text(module(body="def helper(s):\n    return s * 2\n"))
    problems = ip.check(repo)
    assert len(problems) == 1 and "base.py changed since main.py was generated" in problems[0]
    assert "--write fam" in problems[0]


def test_check_fails_on_a_hand_edited_inline_copy(repo):
    write(repo)
    main = repo / "fam" / "main.py"
    main.write_text(main.read_text().replace("return helper(p)", "return helper(p) + 1"))
    problems = ip.check(repo)
    assert len(problems) == 1 and "inline copy of alpha.py was edited by hand" in problems[0]


def test_check_fails_when_family_changes_without_regeneration(repo):
    write(repo)
    (repo / "fam" / "family.py").write_text(family().replace("x = 1", "x = 2"))
    problems = ip.check(repo)
    assert len(problems) == 1 and "family.py changed" in problems[0]


def test_check_fails_on_a_missing_main(repo):
    assert any("fam/main.py drifted" in p for p in ip.check(repo))


def test_check_fails_on_markers_without_a_family(repo):
    write(repo)
    (repo / "orphan").mkdir()
    (repo / "orphan" / "main.py").write_text((repo / "fam" / "main.py").read_text())
    problems = ip.check(repo)
    assert any("orphan/main.py carries inline markers" in p for p in problems)


def test_check_lints_a_module_no_family_inlines_yet(repo):
    write(repo)
    (repo / ip.HARDWARE / "unused.py").write_text(module(body="import os\n"))
    assert any("unused.py" in p and "imports os" in p for p in ip.check(repo))


def test_cli_exit_codes(repo, capsys):
    assert ip.main(["--root", str(repo), "--check"]) == 1
    write(repo)
    assert ip.main(["--root", str(repo), "--check"]) == 0
    assert "1 family cartridge(s) (fam), 0 problem(s)" in capsys.readouterr().out
    with pytest.raises(SystemExit):
        ip.main(["--root", str(repo)])


@pytest.mark.parametrize("directive, message", [
    ("# no directive here", "exactly one `# inline-parts:` line, found 0"),
    ("# inline-parts: alpha\n# inline-parts: alpha", "found 2"),
    ("# inline-parts:", "names no module"),
    ("# inline-parts: alpha alpha", "named twice"),
    ("# inline-parts: missing", "missing.py does not exist"),
    ("# inline-parts: Bad-Name", "is not a module name"),
])
def test_bad_directives_are_refused(repo, directive, message):
    (repo / "fam" / "family.py").write_text(family(directive))
    with pytest.raises(ip.InlineError, match=message.replace("(", r"\(").replace(")", r"\)")):
        ip.generate(repo, "fam")


def test_requirement_cycle_is_refused(repo):
    (repo / ip.HARDWARE / "base.py").write_text(module("alpha", "def helper(s):\n    return s\n"))
    with pytest.raises(ip.InlineError, match="requirement cycle: alpha -> base -> alpha"):
        ip.generate(repo, "fam")


def test_family_shadowing_a_component_is_refused(repo):
    (repo / "fam" / "family.py").write_text(family(extra="def helper(s):\n    return 0\n\n\n"))
    with pytest.raises(ip.InlineError, match="redefines helper"):
        ip.generate(repo, "fam")


def test_two_modules_defining_one_name_are_refused(repo):
    (repo / ip.HARDWARE / "beta.py").write_text(module(body="def helper(s):\n    return s\n"))
    (repo / "fam" / "family.py").write_text(family("# inline-parts: alpha beta"))
    with pytest.raises(ip.InlineError, match="`helper` is defined by both base.py and beta.py"):
        ip.generate(repo, "fam")


def test_a_family_carrying_markers_is_refused(repo):
    write(repo)
    (repo / "fam" / "family.py").write_text((repo / "fam" / "main.py").read_text())
    with pytest.raises(ip.InlineError, match="carries inline markers"):
        ip.generate(repo, "fam")


@pytest.mark.parametrize("text, message", [
    (module(body="import os\n"), "imports os"),
    (module(body="from math import pi\n"), "top-level ImportFrom"),
    (module(body="print('side effect')\n"), "top-level Expr"),
    (module(body="lower = 1\n"), "top-level Assign"),
    (module(body="if True:\n    pass\n"), "top-level If"),
    (module().replace(SPDX, "# SPDX-License-Identifier: MIT"), "first line must be"),
    (module().replace("# requires: \n", ""), "exactly one `# requires:` line"),
    (module() + "\n", "exactly one newline"),
    (module().rstrip("\n"), "exactly one newline"),
    (module(body="def a(:\n"), "does not parse"),
    (module(body="# inline-parts: x\n"), "must not contain"),
    (module(body="def a(p):\n    return p\n" + "\n" * 600), "a module stays at or under 600"),
])
def test_lint_refuses(text, message):
    assert any(message in p for p in ip.lint_module("m", text)), ip.lint_module("m", text)


def test_lint_accepts_the_allowed_shapes():
    body = "import math\nimport cadquery as cq\n\nLIMIT = 2\n\n\ndef a(p):\n    return math.pi * p\n"
    assert ip.lint_module("m", module(body=body)) == []


def test_load_runs_the_inline_order_outside_the_sandbox(repo):
    namespace = ip.load(["alpha"], root=repo)
    assert namespace["a"]("x") == "x" and "helper" in namespace


def test_the_repository_has_no_drift():
    """The manifests lane runs this as its own step too; here it guards the tests."""
    problems = ip.check(REPO)
    assert problems == [], "\n".join(problems)
    assert "clamshell-dual-screen-handheld" in ip.family_slugs(REPO)
